"""Delete a Node from a Doubly Linked List — unlink, guarding both ends.

Time: O(position)   Space: O(1) beyond the list
"""
from typing import List


class _Node:
    __slots__ = ("val", "prev", "next")

    def __init__(self, val):
        self.val = val
        self.prev = None
        self.next = None


class Solution:
    def deleteAt(self, values: List[int], position: int) -> List[int]:
        if position < 0 or position >= len(values):
            return values

        head = tail = None
        for value in values:
            node = _Node(value)
            if head is None:
                head = tail = node
            else:
                tail.next = node
                node.prev = tail
                tail = node

        target = head
        for _ in range(position):
            target = target.next

        if target.prev:
            target.prev.next = target.next
        else:
            head = target.next
        if target.next:
            target.next.prev = target.prev

        out = []
        while head:
            out.append(head.val)
            head = head.next
        return out
